class Wheel { final String id,title; final String? parentId; final List<WheelRay> rays; const Wheel({required this.id,required this.title,this.parentId,required this.rays}); Map<String,dynamic> toJson()=>{'id':id,'title':title,'parentId':parentId,'rays':rays.map((e)=>e.toJson()).toList()}; factory Wheel.fromJson(Map<String,dynamic> j)=>Wheel(id:j['id'],title:j['title'],parentId:j['parentId'],rays:(j['rays'] as List).map((e)=>WheelRay.fromJson(e)).toList()); }
class WheelRay { final String id,title; final String? childWheelId; const WheelRay({required this.id,required this.title,this.childWheelId}); Map<String,dynamic> toJson()=>{'id':id,'title':title,'childWheelId':childWheelId}; factory WheelRay.fromJson(Map<String,dynamic> j)=>WheelRay(id:j['id'],title:j['title'],childWheelId:j['childWheelId']); }
class WheelScore { final String wheelId,rayId; final double value; final DateTime at; const WheelScore({required this.wheelId,required this.rayId,required this.value,required this.at}); Map<String,dynamic> toJson()=>{'wheelId':wheelId,'rayId':rayId,'value':value,'at':at.toIso8601String()}; }
class JournalEntry { final String id,text; final DateTime createdAt; final List<String> wheelIds; const JournalEntry({required this.id,required this.text,required this.createdAt,this.wheelIds=const[]}); Map<String,dynamic> toJson()=>{'id':id,'text':text,'createdAt':createdAt.toIso8601String(),'wheelIds':wheelIds}; }
